window.__finlexDocLoaded(10117,{"id":10117,"articles":[{"id":1000482,"no":"Overview","heading":"Official Overview & Scope (IFRS Foundation)","text":"Superseded by IFRS 15.\n\nIFRIC 15 deals with the timing of revenue recognition by real estate developers for sales of units, such as apartments or houses. The key question is whether the developer is selling a product—the completed apartment or house—or is selling a service—a construction service as a contractor engaged by the buyer. Revenue from selling products is normally recognised at delivery. Revenue from selling construction services is normally recognised proportionally as construction progresses. IFRIC 15 provides guidance for distinguishing between the two.","seq":0},{"id":1000483,"no":"Support","heading":"Related Projects & Implementation Support","text":"[Related IFRS Standards]\n• IAS 11 Construction Contracts\n• IAS 18 Revenue\n• IFRS 15 Revenue from Contracts with Customers","seq":1},{"id":1000484,"no":"References","heading":"Official Text Link & Public Practical Guidance","text":"Official IFRS Foundation Page (English): https://www.ifrs.org/issued-standards/list-of-standards/ifric-15-agreements-for-the-construction-of-real-estate/\nAccess Note: Free access to the unaccompanied text of IFRS Accounting Standards on ifrs.org requires a free registered IFRS.org account; Basis for Conclusions and Illustrative Examples require an IFRS Digital Subscription.\nPublic Companion Overview: KPMG Insights into IFRS — An Overview (Sept 2026): https://assets.kpmg.com/content/dam/kpmgsites/xx/pdf/ifrg/2026/isg-2026-insights-an-overview.pdf","seq":2}]});
